<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {realApi} from '../api/real';
const batch=ref<any>(null),history=ref<any[]>([]),selectedBatch=ref(''),busy=ref(false),error=ref(''),result=ref<any>(null);
const historyLoading=ref(false),message=ref('');
const batchLabels:Record<string,string>={DRAFT:'待核实',APPLIED:'已完成',COMPLETED:'已完成',FAILED:'处理失败',EXPIRED:'已过期',APPLYING:'处理中',SUCCEEDED:'已完成',BOUND:'已绑定',ALREADY_BOUND:'已绑定（无需重复处理）',SKIPPED:'已跳过',CONFLICT:'冲突',VERIFIED:'已核实',ERROR:'处理失败'};
const confirmation=ref<Record<string,boolean>>({}),evidence=ref<Record<string,string>>({}),visibilityConfirmed=ref(false),visibilityEvidence=ref('');
const labels:Record<string,string>={BOUND:'已绑定（保留）',PENDING_VERIFICATION:'待核实',CONFLICT:'绑定冲突',UNMATCHED:'无法匹配',AMBIGUOUS:'候选不唯一',INACTIVE:'飞书身份不可用'};
const errors:Record<string,string>={VERIFICATION_REQUIRED:'必须明确确认并填写可信核实依据。',APP_VISIBILITY_CONFIRMATION_REQUIRED:'请先核实应用可用范围并记录依据。',PREBINDING_EXPIRED:'候选批次已过期，请重新生成并核实。',PREBINDING_RETRY_MISMATCH:'此批次已提交其他记录，不能改变成功批次的提交内容。',PREBINDING_ALREADY_APPLIED:'此批次已完成，请读取结果或重新生成候选。',PREBINDING_ITEM_NOT_ELIGIBLE:'该记录不可批量绑定，请通过异常流程处理。',FEISHU_BINDING_CONFLICT:'飞书身份已关联其他成员。',FEISHU_ACCOUNT_ALREADY_BOUND:'成员已有其他有效绑定。',FEISHU_IDENTITY_UNAVAILABLE:'该身份已不在可读取有效通讯录中。',BATCH_NOT_COMMITTED:'整批未写入，请先处理失败项。',FORBIDDEN:'当前账号没有组织范围的绑定管理权限。'};
const ready=computed(()=>batch.value?.items.filter((i:any)=>i.match_status==='PENDING_VERIFICATION'&&i.verified_by&&i.verified_open_id)??[]);
const draft=computed(()=>batch.value?.status==='DRAFT');
function explain(e:any){return errors[e?.code]??e?.message??'请求失败，请重试。';}
function install(data:any){batch.value=data;selectedBatch.value=data.id;result.value=data.lastResult;confirmation.value=Object.fromEntries(data.items.map((i:any)=>[i.id,!!i.verified_by]));evidence.value=Object.fromEntries(data.items.map((i:any)=>[i.id,i.verification_evidence??'']));visibilityConfirmed.value=false;visibilityEvidence.value='';}
async function loadHistory(){historyLoading.value=true;try{history.value=await realApi.listPrebindingBatches();}finally{historyLoading.value=false;}}
async function retryHistory(){error.value='';try{await loadHistory();}catch(e){error.value=explain(e);}}
onMounted(async()=>{try{await loadHistory();}catch(e){error.value=explain(e);}});
async function preview(){busy.value=true;error.value='';message.value='';try{install(await realApi.previewPrebindings());message.value='候选清单已生成，请逐项核实身份。';await loadHistory();}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function select(){if(!selectedBatch.value){batch.value=null;result.value=null;message.value='';return;}busy.value=true;error.value='';message.value='';try{install(await realApi.getPrebindingBatch(selectedBatch.value));}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function verify(item:any){busy.value=true;error.value='';try{install(await realApi.verifyPrebinding(batch.value.id,item.id,confirmation.value[item.id]===true,item.candidates_json[0]?.openId,evidence.value[item.id]??''));message.value='核实信息已保存。';}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function submit(){busy.value=true;error.value='';message.value='';const id=batch.value.id;try{result.value=await realApi.submitPrebindings(id,ready.value.map((i:any)=>i.id),visibilityConfirmed.value,visibilityEvidence.value);install(await realApi.getPrebindingBatch(id));message.value=result.value?.committed?'已核实的绑定已提交成功。':'';await loadHistory();}catch(e:any){error.value=explain(e);if(e.detail?.items)result.value=e.detail;}finally{busy.value=false;}}
</script>
<template>
 <section class="card prebinding-panel" aria-labelledby="prebinding-title" :aria-busy="busy||historyLoading">
  <header class="section-heading"><h2 id="prebinding-title">飞书账号批量预绑定</h2><p>姓名和部门仅用于候选提示，须逐项核实后提交。不会创建成员或改变部门、角色和权限。</p></header>
  <p v-if="error" class="notice notice-error" role="alert">{{error}} <button class="btn" :disabled="busy||historyLoading" @click="retryHistory">重新读取批次</button></p>
  <p v-if="message" class="notice notice-success" role="status">{{message}}</p>
  <div class="prebinding-toolbar"><button class="btn btn-primary" :disabled="busy||historyLoading" @click="preview">{{busy?'正在处理…':'生成新的候选清单'}}</button><label for="prebinding-history"><span>历史批次</span><select id="prebinding-history" v-model="selectedBatch" :disabled="busy||historyLoading" @change="select"><option value="">{{historyLoading?'正在加载批次…':'选择历史批次'}}</option><option v-for="h in history" :key="h.id" :value="h.id">{{new Date(h.created_at).toLocaleString('zh-CN',{dateStyle:'short',timeStyle:'short'})}} · {{batchLabels[h.status]??'状态待核实'}}</option></select></label><span v-if="!historyLoading&&!history.length&&!error" class="history-empty">暂无历史批次，生成候选清单后可在此查看。</span></div>
  <p v-if="busy" class="processing-state" role="status">正在处理，请稍候，避免重复操作。</p>
  <template v-if="batch">
   <div class="batch-heading"><span class="batch-status">{{batchLabels[batch.status]??'状态待核实'}}</span><span>有效期至 {{new Date(batch.expiresAt).toLocaleString('zh-CN')}}</span><details><summary>批次与应用信息</summary><p>批次：{{batch.id}}<br>租户：{{batch.tenantKey}}<br>应用：{{batch.appId}}</p></details></div>
   <div class="summary"><span v-for="(count,key) in batch.summary" :key="key">{{labels[key]??'其他状态'}} <strong>{{count}}</strong></span><span>已明确核实 <strong>{{ready.length}}</strong></span></div>
   <div class="table-wrap"><table class="table candidate-table"><colgroup><col style="width:20%"><col style="width:30%"><col style="width:20%"><col style="width:30%"></colgroup><thead><tr><th scope="col">内部成员</th><th scope="col">飞书候选</th><th scope="col">绑定与匹配状态</th><th scope="col">管理员核实</th></tr></thead><tbody>
    <tr v-for="item in batch.items" :key="item.id"><td><strong>{{item.member_name}}</strong><p>{{item.department_name||'未分配部门'}}</p><small class="identifier">{{item.user_id}}</small></td>
     <td><div v-for="candidate in item.candidates_json" :key="candidate.openId" class="candidate"><strong>{{candidate.name}}</strong><p>{{candidate.departmentNames.join('、')||'未返回部门'}}</p><small class="identifier">身份标识：{{candidate.openId}}<br>用户标识：{{candidate.userId||'当前权限未返回'}}</small><span class="state-tag" :class="candidate.active?'state-valid':'state-muted'">{{candidate.active?'通讯录身份有效':'身份不可用'}}</span></div><span v-if="!item.candidates_json.length" class="muted">没有同名候选，需另行核实处理。</span></td>
     <td><span class="state-tag" :class="item.match_status==='BOUND'?'state-valid':item.match_status==='PENDING_VERIFICATION'?'state-pending':'state-muted'">{{labels[item.match_status]??'状态待核实'}}</span><p v-for="binding in item.bindings_json" :key="binding.id" class="binding-note">原绑定：<span class="identifier">{{binding.openId}}</span>{{binding.approved?'已批准':'未批准 / 已撤销'}}</p></td>
     <td><template v-if="draft&&item.match_status==='PENDING_VERIFICATION'"><label class="check-label"><input v-model="confirmation[item.id]" type="checkbox" :disabled="busy" :aria-label="'确认身份 '+item.user_id"><span>我已独立核实该成员与此飞书身份对应</span></label><textarea v-model="evidence[item.id]" rows="2" maxlength="500" :disabled="busy" :aria-label="'核实依据 '+item.user_id" placeholder="填写可信名册或独立渠道核实依据，勿填写令牌、Cookie或密码"></textarea><button class="btn" :disabled="busy||confirmation[item.id]&&!evidence[item.id]?.trim()" @click="verify(item)">保存核实</button></template><p v-if="item.verified_by" class="verification-note">核实人：{{item.verified_by_name||item.verified_by}}<br>{{item.verification_evidence}}<br>{{new Date(item.verified_at).toLocaleString('zh-CN')}}</p><span v-if="!item.verified_by&&item.match_status!=='PENDING_VERIFICATION'" class="muted">不参与批量提交</span></td>
    </tr><tr v-if="!batch.items.length"><td colspan="4" class="panel-state">此批次暂无候选成员。</td></tr>
   </tbody></table></div>
   <section v-if="draft" class="visibility"><h3>应用可用范围核查</h3><p>通讯录可读不代表成员均可登录。请在飞书后台核实本次提交成员的应用可用范围，此操作不会扩大飞书权限。</p><label class="check-label"><input v-model="visibilityConfirmed" type="checkbox" :disabled="busy"><span>已在飞书后台核实本次提交成员的应用可用范围</span></label><textarea v-model="visibilityEvidence" :disabled="busy" maxlength="500" rows="2" aria-label="应用可用范围核查依据" placeholder="记录后台核查时间、核实依据或审批记录"></textarea><div class="submission-row"><p>将提交 {{ready.length}} 条已保存核实的记录。任一条失败则整批不写入。</p><button class="btn btn-primary" :disabled="busy||!ready.length||!visibilityConfirmed||!visibilityEvidence.trim()" @click="submit">{{busy?'正在提交…':'提交已核实绑定'}}</button></div><details><summary>查看接口核查结果</summary>{{batch.visibility.providerCode??'未验证'}}</details></section>
   <div v-if="result" class="batch-result" :class="result.committed?'result-success':'result-failed'" role="status"><h3>{{result.committed?'批次已完成':'整批未写入任何绑定'}}</h3><ul><li v-for="r in result.items" :key="r.itemId">{{batch.items.find((i:any)=>i.id===r.itemId)?.member_name??r.userId??r.itemId}}：{{batchLabels[r.status]??labels[r.status]??'待核实'}} <span v-if="r.code">{{errors[r.code]??'请核对处理详情后重试'}}</span></li></ul></div>
  </template>
 </section>
</template>
<style scoped>
.prebinding-panel{min-width:0}.section-heading p{margin:8px 0 0;color:var(--lark-text-2);font-size:13px;line-height:21px}.prebinding-toolbar{display:flex;flex-wrap:wrap;gap:16px;align-items:flex-end;margin:20px 0 0}.prebinding-toolbar>label{display:flex;flex-direction:column;gap:7px;color:var(--lark-text-2);font-size:12px;min-width:220px;max-width:100%}.prebinding-toolbar select{width:100%}.history-empty{font-size:12px;line-height:36px;color:var(--lark-text-3)}.processing-state{color:var(--lark-primary);font-size:13px;margin:14px 0 0}.batch-heading{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:20px 0 14px;color:var(--lark-text-3);font-size:12px}.batch-heading details{min-width:0}.batch-heading details p{overflow-wrap:anywhere;line-height:21px}.batch-status{padding:3px 8px;border-radius:4px;background:#eef4ff;color:#3370ff}.summary{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.summary>span{padding:5px 9px;background:#f5f7fb;border-radius:5px;color:#748196;font-size:12px}.summary strong{margin-left:6px;color:#344054}.candidate-table{min-width:960px;table-layout:fixed}.candidate-table td{vertical-align:top;white-space:normal;overflow-wrap:anywhere}.candidate-table p{margin:5px 0;font-size:12px;line-height:20px;color:var(--lark-text-2)}.identifier{font-size:11px;line-height:19px;color:var(--lark-text-3);overflow-wrap:anywhere;display:block}.candidate+.candidate{padding-top:12px;margin-top:12px;border-top:1px solid #edf1f6}.state-tag{display:inline-flex;margin-top:4px;padding:2px 7px;border-radius:4px;font-size:12px;line-height:19px}.state-valid{background:#edf8f2;color:#238263}.state-pending{background:#fff6e8;color:#b77715}.state-muted{background:#f1f3f6;color:#748196}.muted{color:var(--lark-text-3);font-size:12px}.check-label{display:flex;align-items:flex-start;gap:7px;font-size:12px;line-height:20px;color:var(--lark-text-2)}input[type=checkbox]{width:14px;min-height:14px;margin:3px 0 0;flex:none}textarea{display:block;width:100%;margin:10px 0;min-height:68px}.visibility{background:#f8faff;border:1px solid #e5edf9;padding:18px;border-radius:8px;margin-top:18px}.visibility h3,.batch-result h3{font-size:15px;margin:0 0 8px}.visibility p{color:var(--lark-text-2);font-size:12px;line-height:21px;margin:0 0 12px}.visibility details{font-size:12px;color:var(--lark-text-3);margin-top:12px}.submission-row{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:12px}.submission-row p{margin:0}.submission-row .btn{flex:none}.panel-state{text-align:center;color:var(--lark-text-3);padding:24px!important}.batch-result{padding:16px;border-radius:8px;margin-top:16px;font-size:13px}.batch-result ul{margin:0;padding-left:20px;line-height:24px}.result-success{background:#effaf4;color:#238263}.result-failed{background:#fff7ed;color:#ad6b16}@media(max-width:760px){.prebinding-toolbar{align-items:flex-end;gap:12px}.prebinding-toolbar>.btn{align-self:flex-end;flex:none}.prebinding-toolbar>label{flex:1;min-width:160px}.history-empty{width:100%;line-height:20px}.submission-row{align-items:stretch;flex-direction:column}.visibility{padding:14px}}
</style>
